INSERT INTO module_questions (module_id, level, question, options, correct_index, explanation, xp_reward) VALUES
('gate-puzzler','advanced','A 3-variable K-map has how many cells?',ARRAY['8','4','16','32'],0,'2^3 = 8 cells.',20),
('gate-puzzler','advanced','A 4-variable K-map has how many cells?',ARRAY['16','8','32','64'],0,'2^4 = 16 cells.',20),
('gate-puzzler','advanced','A 5-variable K-map has how many cells?',ARRAY['32','16','64','128'],0,'2^5 = 32 cells.',20),
('gate-puzzler','advanced','In a K-map, adjacent cells differ by how many variables?',ARRAY['1','2','3','0'],0,'Gray code ordering: adjacent cells differ by 1 variable.',20),
('gate-puzzler','advanced','What is the maximum group size in a 4-variable K-map?',ARRAY['16','8','4','2'],0,'All 16 cells = function = 1.',20),
('gate-puzzler','advanced','K-map groups must be of what size?',ARRAY['Powers of 2','Any number','Odd numbers','Prime numbers'],0,'Groups of 1, 2, 4, 8, 16...',20),
('gate-puzzler','advanced','What does a K-map with all 1s simplify to?',ARRAY['1','0','A','A'''],0,'All 1s = constant 1.',20),
('gate-puzzler','advanced','What does a K-map with all 0s simplify to?',ARRAY['0','1','A','A'''],0,'All 0s = constant 0.',20),
('gate-puzzler','advanced','What is a prime implicant in K-map simplification?',ARRAY['A maximal group of 1s','Any group of 1s','A single cell','A group of 0s'],0,'Prime implicant = largest possible group.',20),
('gate-puzzler','advanced','What is an essential prime implicant?',ARRAY['Covers a cell no other PI covers','The largest group','The smallest group','Any group'],0,'Essential PI covers at least one unique minterm.',20),
('gate-puzzler','advanced','How many minterms in F(A,B,C) = Σm(0,1,2,5)?',ARRAY['4','3','5','8'],0,'Four minterms: m0, m1, m2, m5.',20),
